'use strict';
const economicsPair = ['knoebels-amusement-resort', 'efteling'];
const paymentSources = {
  'knoebels-amusement-resort': 'https://knoebels.com/info/pricing/',
  efteling: 'https://www.efteling.com/en/park/information/ticket-overview'
};

function parkFinding(park, key, value) {
  return '#park/' + park.id + '?' + new URLSearchParams({[key]: value});
}

function copyControl(hash, label = 'Скопировать ссылку') {
  return `<button type="button" class="copy-finding" data-copy="${esc(hash)}">${esc(label)}</button>`;
}

async function copyFinding(hash) {
  const base = location.protocol === 'file:' ? 'https://konstantinpopov89.github.io/world-parks-atlas/' : location.href;
  const url = new URL(hash, base).href;
  try {
    await navigator.clipboard.writeText(url);
    toast('Ссылка скопирована');
  } catch {
    window.prompt('Скопируйте ссылку', url);
  }
}

function economicsExamples() {
  const compare = '#compare?' + new URLSearchParams({parks: economicsPair.join(','), row: 'payment'});
  return `<section class="chapter-example" id="companion">
    <h2>Что заплатит сопровождающий, который не катается?</h2>
    <div class="companion-pair">
      <article><h3><a href="#park/knoebels-amusement-resort?part=knoebels-amusement-resort-section-4">Кноэбелс</a></h3>
      <p>Вход свободный. Взрослый может провести день с семьёй без покупки билета на катание. Для тех, кто катается, есть билеты на поездки и пропуск на отдельные дни.</p>
      ${link(paymentSources['knoebels-amusement-resort'], 'Как оплачиваются поездки')}</article>
      <article><h3><a href="#park/efteling?part=passport">Эфтелинг</a></h3>
      <p>Обычному взрослому посетителю нужен входной билет, даже если он хочет только гулять по Сказочному лесу. Цена входа зависит от дня посещения.</p>
      ${link(paymentSources.efteling, 'Условия входного билета')}</article>
    </div><a class="tag" href="${esc(compare)}">Сравнить два парка по оплате</a></section>`;
}

const rainExamples = [
  {id: 'puzzling-world', section: 'puzzling-world-section-5',
    reason: 'При дожде можно выбрать крытые комнаты иллюзий. Открытый лабиринт и комнаты продаются отдельно или вместе.'},
  {id: 'hanayashiki', section: 'hanayashiki-section-4',
    reason: 'Руководитель парка связывает обновление крытых развлечений с жарой и ливнями. Гости могут зайти в помещения во время прогулки по Асакусе.'}
];

function ideaRecovery(q, region, topic, topics, all) {
  const parkPool = PARKS.filter(p => !region || p.region === region);
  const rain = /дожд|ливн|ливен/u.test(norm(q));
  let catalogQuery = q;
  let catalogCount = q ? parkPool.filter(p => matches(searchText(p), q)).length : 0;
  if (!catalogCount && rain) {
    catalogQuery = 'дождь';
    catalogCount = parkPool.filter(p => matches(searchText(p), catalogQuery)).length;
  }
  const examples = rain ? rainExamples.filter(x => !region || byId[x.id].region === region) : [];
  const actions = [];
  if (rain && all.some(x => (!region || x.p.region === region) && x.i.topics?.includes('weather'))) {
    const params = new URLSearchParams({topic: 'weather'});
    if (region) params.set('region', region);
    actions.push(`<a href="#ideas?${esc(params)}">${esc(topics.weather)}</a>`);
  }
  if (catalogCount) {
    const params = new URLSearchParams({q: catalogQuery});
    if (region) params.set('region', region);
    actions.push(`<a href="#catalog?${esc(params)}">Посмотреть ${catalogCount} ${plural(catalogCount, 'парк', 'парка', 'парков')} в каталоге</a>`);
  }
  if (q || region || topic) actions.push('<a href="#ideas">Все идеи</a>');
  const related = examples.map(x => {
    const p = byId[x.id];
    const finding = parkFinding(p, 'part', x.section);
    return `<article><h3><a href="${esc(finding)}">${esc(p.name_ru)}</a></h3><p>${esc(x.reason)}</p></article>`;
  }).join('');
  return `<div class="empty search-recovery">
    ${related ? '<h2>Как парки работают в дождь</h2>' + related : '<p>По заданным условиям идей не найдено.</p>'}
    <div class="actions">${actions.join('')}</div></div>`;
}

function comparisonParks(params = new URLSearchParams(location.hash.split('?')[1])) {
  if (params.get('parks') === economicsPair.join(',')) return economicsPair.map(id => byId[id]);
  return compared.map(id => byId[id]).filter(Boolean);
}

function readingPosition(anchor) {
  const container = anchor?.closest('article[id]');
  return {hash: location.hash, y: window.scrollY,
    anchor: container?.id, offset: container?.getBoundingClientRect().top};
}

function rememberReadingPlace(anchor) {
  history.replaceState({...history.state, atlasPlace: readingPosition(anchor)}, '');
}

// Save the entry being left before the browser switches to a new fragment.
history.scrollRestoration = 'manual';
document.addEventListener('click', event => {
  const a = event.target.closest('a[href^="#"]');
  if (!a || event.ctrlKey || event.metaKey || event.shiftKey || event.altKey || a.target === '_blank') return;
  if (a.hash !== location.hash) {
    rememberReadingPlace(a);
  } else if (a.closest('.toc-small')) {
    event.preventDefault();
    const params = new URLSearchParams(a.hash.split('?')[1]);
    document.getElementById(params.get('part'))?.scrollIntoView({block: 'start'});
  }
}, true);

function finishNavigation(pageName, parkId, params, place) {
  if (place?.hash === location.hash) {
    const anchor = place.anchor && document.getElementById(place.anchor);
    const top = anchor ? window.scrollY + anchor.getBoundingClientRect().top - place.offset : place.y;
    window.scrollTo(0, top);
    return;
  }
  let target = null;
  if (pageName === 'park' && byId[parkId]) {
    const p = byId[parkId];
    const photoId = params.get('photo');
    if (photoId && p.photos?.some(ph => ph.id === photoId)) {
      const trigger = [...main.querySelectorAll('button[data-photo]')].find(b => b.dataset.photo === photoId);
      trigger?.focus({preventScroll:true});
      showLight(parkId, photoId);
      return;
    }
    const part = params.get('part'), ideaId = params.get('idea');
    if (part) target = document.getElementById(part);
    if (ideaId) target = document.getElementById('idea-' + parkId + '-' + ideaId);
    if (target && !main.contains(target)) target = null;
  }
  if (target) target.scrollIntoView({block:'start'}); else window.scrollTo(0, 0);
}

function linkParkSections(p) {
  for (const section of main.querySelectorAll('.reading > section[id], .park-passport')) {
    const heading = section.querySelector('h2');
    if (heading) heading.insertAdjacentHTML('afterend', copyControl(parkFinding(p, 'part', section.id), 'Ссылка на раздел'));
  }
}

