function searchText(p){if(searchCache.has(p.id))return searchCache.get(p.id);const content=[p.name_ru,p.original_name,p.city_ru,p.country_ru,p.summary,p.operator,p.opened,p.seasonality,p.status?.label,p.payment_model,p.theme_level,p.context,...(p.audience||[]),...(p.types||[]),...(p.types||[]).map(t=>TYPES[t]),...(p.highlights||[]).flatMap(x=>[x.title,x.text]),...(p.sections||[]).flatMap(x=>[x.title,x.text]),...(p.ideas||[]).flatMap(i=>[i.title,i.observation,i.mechanism,i.conditions,i.limits,i.photo_hint]),...Object.values(p.swot||{}).flat().map(txt),...(p.reviews||[]).map(x=>x.summary),...(p.numbers||[]).map(x=>[x.label,x.value,x.unit,x.year,x.scope].join(' ')),...(p.attraction_links||[]).flatMap(x=>[x.ride,x.zone,x.manufacturer,x.model]),...(p.photos||[]).map(x=>x.caption_ru)];const text=norm(content.join(' '));searchCache.set(p.id,text);return text;}

