function plural(n,a,b,c){return n%10===1&&n%100!==11?a:n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?b:c;}
function numberText(n){return `${n.value??'Не установлено'} ${n.unit||''}${n.year?` · ${n.year}`:' · год характеристики не указан'}${n.scope?` · ${n.scope}`:''}`;}
function idea(p,i,standalone=false){const matches=(i.photo_ids||[]).map(id=>p.photos?.find(ph=>ph.id===id)).filter(Boolean);return `<article class="idea" id="idea-${esc(p.id)}-${esc(i.id)}"><p class="kind-label">Редакционный разбор${standalone?` · ${esc(p.name_ru)}`:''}</p><h3>${esc(i.title)}</h3>${copyControl(parkFinding(p,"idea",i.id),"Ссылка на идею")}<p>${esc(i.observation)} ${sources(p,i.source_ids)}</p><div class="idea-grid"><div><label>Как может работать</label><p>${esc(i.mechanism)}</p><label>Условия переноса</label><p>${esc(i.conditions)}</p></div><div><label>Граница применимости</label><p>${esc(i.limits)}</p>${i.photo_hint?`<label>Что рассмотреть</label><p>${esc(i.photo_hint)}</p>`:''}</div></div>${matches.length?`<div class="idea-photo">${matches.map(ph=>`<button data-photo="${ph.id}" data-park="${p.id}" aria-label="Рассмотреть: ${esc(photoCaption(p,ph))}"><img src="${esc(ph.thumb||ph.file)}" loading="lazy" alt="${esc(photoCaption(p,ph))}"></button>`).join('')}</div>`:''}${standalone?`<a class="small" href="#park/${p.id}">Разобрать ${esc(p.name_ru)} →</a>`:''}</article>`;}
function parkPage(p){if(!p){main.innerHTML=header('Каталог','Парк не найден')+'<p><a href="#catalog">Вернуться к каталогу</a></p>';return;}const ph=p.photos?.[0],sections=p.sections||[];const hero=ph?`<figure class="park-hero"><button data-photo="${ph.id}" data-park="${p.id}" style="border:0;padding:0;width:100%;background:transparent" aria-label="Увеличить фотографию"><img src="${esc(ph.file)}" width="${Number(ph.width)||1200}" height="${Number(ph.height)||800}" alt="${esc(photoCaption(p,ph))}"></button><figcaption>${esc(photoCaption(p,ph))} · ${photoCreditHTML(ph)}</figcaption></figure>`:'';const passport=[['Страна и город',[p.country_ru,p.city_ru].filter(Boolean).join(', ')],['Формат',(p.types||[]).map(t=>TYPES[t]||t).join(' · ')],['Масштаб и роль',SCALES[p.scale]||p.scale],['Аудитория',(p.audience||[]).join('; ')||'Не выделена по источникам'],['Тематизация',p.theme_level||'Не выделена по источникам'],['Контекст',p.context||'Не установлен'],['Модель оплаты',p.payment_model||'Проверяйте условия конкретного билета'],['Среда',SETTINGS[p.setting]||p.setting],['Оператор',p.operator||'Не установлен по изученным источникам'],['Открытие',p.opened||'Не установлено'],['Сезонность',p.seasonality||'Проверяйте актуальный календарь'],['Сайт',link(p.website,'Официальный сайт')]];main.innerHTML=`<div class="crumbs"><a href="#catalog">Каталог</a> / <a href="#catalog?region=${p.region}">${esc(REGIONS[p.region])}</a> / ${esc(p.country_ru)}</div><div class="page-top"><div><p class="eyebrow">${p.deep?'Подробный разбор':'Карточка парка'} · ${esc(p.city_ru||p.country_ru)}</p><h1 class="park-title">${esc(p.name_ru)}</h1>${p.original_name!==p.name_ru?`<p class="original">${esc(p.original_name)}</p>`:''}</div>${actions(p)}</div><p class="lead">${esc(p.summary)}</p>${hero}<section class="park-passport" id="passport"><h2>Паспорт парка</h2><dl class="passport">${passport.map(([a,b])=>`<div><dt>${a}</dt><dd>${a==='Сайт'?b:esc(b)}</dd></div>`).join('')}</dl></section>${p.coordinates?.length===2?`<p class="small muted">Геометка: ${esc(p.coordinates[1])}, ${esc(p.coordinates[0])}. ${link(p.coordinates_source,'Источник координат')}${p.coordinates_note||p.coordinates_notes?` · ${esc(p.coordinates_note||p.coordinates_notes)}`:''}</p>`:''}${p.classification_source_ids?.length?`<p class="small muted">Источники классификации и модели посещения: ${sources(p,p.classification_source_ids)}</p>`:''}<div class="status-note">${esc(p.status?.label||'Статус уточняется')} ${p.status?.as_of?`· проверка ${esc(p.status.as_of)}`:''} ${sources(p,p.status?.source_ids)}. Состав работающих аттракционов и календарь уточняйте перед посещением.</div><div class="highlight-list">${(p.highlights||[]).map(h=>`<article><h3>${esc(h.title)}</h3><p>${esc(h.text)} ${sources(p,h.source_ids)}</p></article>`).join('')}</div><div class="detail-layout"><div class="reading">${sections.map(s=>`<section id="${esc(s.id)}">${s.kind==='analysis'?'<div class="kind-label">Редакционная интерпретация</div>':''}<h2>${esc(s.title)}</h2>${paras(s.text)}${sources(p,s.source_ids)}</section>`).join('')}${p.numbers?.length?`<section id="numbers"><h2>Цифры с границами</h2>${p.numbers.map(n=>`<p><strong>${esc(n.label)}:</strong> ${esc(numberText(n))} ${sources(p,n.source_ids)}</p>`).join('')}<p class="small muted">Год и область учета важны: показатели парка, курорта и оператора нельзя складывать или сравнивать без приведения к одному основанию.</p></section>`:''}${attractionLinks(p)}${p.swot?`<section id="swot"><h2>Четыре стороны решения</h2><p class="small muted">Редакционная оценка по источникам. Это не рейтинг и не прогноз окупаемости.</p><div class="swot">${Object.entries({strengths:'Сильные стороны',weaknesses:'Ограничения',opportunities:'Возможности',threats:'Риски'}).map(([k,n])=>`<div><h3>${n}</h3><ul>${(p.swot[k]||[]).map(x=>`<li>${esc(txt(x))} ${sources(p,x.source_ids)}</li>`).join('')}</ul></div>`).join('')}</div></section>`:''}${p.ideas?.length?`<section id="ideas"><h2>Идеи для переноса</h2>${p.ideas.map(i=>idea(p,i)).join('')}</section>`:''}${p.reviews?.length?`<section id="reviews"><h2>Свидетельства и опыт</h2>${p.reviews.map(r=>`<div class="idea"><div class="kind-label">${r.kind==='guest'?'Мнение гостя':'Опыт оператора'}${r.date?` · ${esc(r.date)}`:''}</div><p>${esc(r.summary)}</p><p class="small muted">${esc(r.scope||'Отдельное свидетельство, не репрезентативный рейтинг.')} ${link(r.url,'Источник')}</p></div>`).join('')}</section>`:p.deep?`<section id="reviews"><h2>Свидетельства и опыт</h2><p class="small muted">${esc(p.review_search?.limitations||'В использованных материалах не выделено достаточно надежных независимых свидетельств для отдельного разбора. Это не означает отсутствия отзывов.')}</p></section>`:''}<section id="photos"><div class="section-head"><h2>Рассмотреть парк</h2><span class="photo-count">${p.photos?.length||0} фото</span></div>${gallery(p)}</section><section id="practical"><h2>Продолжить изучение</h2><div class="actions">${p.practical?.plan_url?link(p.practical.plan_url,p.practical.plan_label||'Официальный план / карта'):''}${p.practical?.accessibility_url?link(p.practical.accessibility_url,'Доступность'):''}${p.practical?.visitor_info_url?link(p.practical.visitor_info_url,'Информация посетителю'):''}${p.wiki_title?link('https://'+(p.wiki_language||'en')+'.wikipedia.org/wiki/'+encodeURIComponent(p.wiki_title),'Энциклопедическая справка'):''}</div><p class="small muted">${p.practical?.plan_note?esc(p.practical.plan_note)+" ":""}Внешние ссылки открываются при подключении к интернету. План парка может относиться к указанному в источнике сезону.</p></section><section id="source-list"><h2>Источники карточки</h2>${sourceList(p.sources||[])}</section></div><aside><div class="toc-small"><p>В этом разборе</p>${sections.map(s=>`<a href="${esc(parkFinding(p,"part",s.id))}">${esc(s.title)}</a>`).join('')}${p.ideas?.length?`<a href="${esc(parkFinding(p,'part','ideas'))}">Идеи для переноса</a>`:''}<a href="${esc(parkFinding(p,'part','photos'))}">Фотографии</a><a href="${esc(parkFinding(p,'part','source-list'))}">Источники</a></div></aside></div>`;linkParkSections(p);}
function gallery(p){const limitations=(p.photo_limitations||[]).map(x=>`<p class="note">${esc(x)}</p>`).join('');if(!p.photos?.length)return `${limitations}<p class="note">В этой версии нет фотографий с подтвержденной привязкой и условиями использования. ${link(p.website,'Официальный сайт парка')}</p>`;return `${limitations}<div class="gallery">${p.photos.map(ph=>`<figure><button data-photo="${ph.id}" data-park="${p.id}" aria-label="Увеличить: ${esc(photoCaption(p,ph))}"><img src="${esc(ph.thumb||ph.file)}" alt="${esc(photoCaption(p,ph))}" loading="lazy" width="560" height="370"></button><figcaption>${esc(photoCaption(p,ph))}<span class="credit">${photoCreditHTML(ph)} · ${link(ph.source_page,'Источник')}</span></figcaption></figure>`).join('')}</div>`;}
function sourceList(ss){return `<ol class="sources-list">${ss.map((s,i)=>`<li><span>[${i+1}] ${esc(({official:'Официальный источник',operator:'Оператор',industry:'Отраслевой источник','public-authority':'Публичный орган',encyclopedia:'Энциклопедия',guest:'Гость'})[s.kind]||s.kind||'Источник')}</span><br>${link(s.url,s.title||s.url)}<br><span>${s.published_on?`Дата материала: ${esc(s.published_on)} · `:''}${s.checked_on?`Проверено ${esc(s.checked_on)}`:''}</span></li>`).join('')}</ol>`;}
function showLight(pid,photoId){const p=byId[pid];if(!p)return;lightPhotos=p.photos||[];lightIndex=Math.max(0,lightPhotos.findIndex(ph=>ph.id===photoId));returnFocus=document.activeElement;$('#lightbox').dataset.park=pid;updateLight();if(!$('#lightbox').open)$('#lightbox').showModal();$('#lightbox .light-close').focus();}
function updateLight(){const p=byId[$('#lightbox').dataset.park],ph=lightPhotos[lightIndex];if(!ph)return;
  const [routeHash,query]=location.hash.split('?');
  const params=new URLSearchParams(query);
  if(routeHash==='#park/'+p.id && params.has('photo') && params.get('photo')!==ph.id){
    params.set('photo',ph.id);
    history.replaceState(history.state,'',routeHash+'?'+params);
  }
  $('#light-img').src=ph.file;$('#light-img').alt=photoCaption(p,ph);$('#light-caption').innerHTML=`${lightIndex+1} / ${lightPhotos.length} · ${esc(p.name_ru)}<br>${esc(photoCaption(p,ph))}<br><span class="small">${photoCreditHTML(ph)}${ph.date?` · Дата в источнике: ${esc(ph.date)}`:''} · ${link(ph.source_page,'Страница изображения')}</span>${copyControl(parkFinding(p,'photo',ph.id),'Ссылка на фото')}`;$('#lightbox .light-prev').disabled=lightPhotos.length<2;$('#lightbox .light-next').disabled=lightPhotos.length<2;}
$('#lightbox .light-close').onclick=()=>$('#lightbox').close();$('#lightbox .light-prev').onclick=()=>{lightIndex=(lightIndex-1+lightPhotos.length)%lightPhotos.length;updateLight();};$('#lightbox .light-next').onclick=()=>{lightIndex=(lightIndex+1)%lightPhotos.length;updateLight();};$('#lightbox').addEventListener('close',()=>{
  const [path,query]=location.hash.split('?');
  const params=new URLSearchParams(query);
  if(params.has('photo') && !$('#lightbox').open){
    params.delete('photo');
    history.replaceState(history.state,'',path+(params.size?'?'+params:''));
  }
  if(returnFocus?.isConnected && !$('#lightbox').open) returnFocus.focus();
});$('#lightbox').addEventListener('keydown',e=>{if(e.key==='ArrowLeft')$('#lightbox .light-prev').click();if(e.key==='ArrowRight')$('#lightbox .light-next').click();});
function mapPage(){const plotted=PARKS.filter(p=>p.coordinates?.length===2),missing=PARKS.filter(p=>p.coordinates?.length!==2);main.innerHTML=`${header('География','Мир парков','Найдите парк по названию или приблизьте регион. Точка открывает карточку, а список стран остается доступен под картой.')}<div class="map-controls"><label>Регион <select id="map-region"><option value="">Весь мир</option>${Object.entries(REGIONS).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>Название <input id="map-search" type="search" placeholder="Парк или город"></label><button id="map-plus" aria-label="Приблизить карту">+</button><button id="map-minus" aria-label="Отдалить карту">−</button><button id="map-reset">Весь мир</button></div><div class="world-map"><svg id="atlas-map" viewBox="0 0 1000 500" role="group" aria-label="Интерактивная карта парков"><g>${(DB.map?.paths||[]).map(p=>`<path class="land" d="${p.path}"/>`).join('')}</g><g>${plotted.map(p=>`<a href="#park/${p.id}" data-map-park="${p.id}" aria-label="${esc(p.name_ru+', '+p.country_ru)}"><circle class="dot" cx="${((p.coordinates[0]+180)*1000/360).toFixed(2)}" cy="${((85-p.coordinates[1])*500/170).toFixed(2)}" r="${p.deep?4:2.8}"><title>${esc(p.name_ru)} · ${esc(p.country_ru)}</title></circle></a>`).join('')}</g></svg></div><p id="map-match" class="small" aria-live="polite"></p><p class="legend">Крупные точки: подробные разборы. Масштаб меняется кнопками; карту можно перетаскивать. Координаты показывают общее расположение, не вход или маршрут внутри парка. Основа: Natural Earth, public domain.</p>${missing.length?`<p class="note">Координаты не установлены по использованным источникам для ${missing.length} объектов: ${missing.map(p=>`<a href="#park/${p.id}">${esc(p.name_ru)}</a>`).join(', ')}. Их карточки доступны в каталоге.</p>`:''}<div class="region-list">${Object.entries(REGIONS).map(([id,n])=>`<a href="#catalog?region=${id}">${n}<span>${PARKS.filter(p=>p.region===id).length}</span></a>`).join('')}</div><div class="section-head"><h2>Страны и территории</h2></div><div class="region-list">${[...new Set(PARKS.map(p=>p.country_ru))].sort((a,b)=>a.localeCompare(b,'ru')).map(c=>`<a href="#catalog?country=${encodeURIComponent(c)}">${esc(c)}<span>${PARKS.filter(p=>p.country_ru===c).length}</span></a>`).join('')}</div>`;const svg=$('#atlas-map');let box=[0,0,1000,500],drag=null,moved=false;function apply(){svg.setAttribute('viewBox',box.join(' '));svg.querySelectorAll('circle').forEach(c=>{const p=byId[c.parentElement.dataset.mapPark];c.setAttribute('r',(p.deep?4:2.8)*box[2]/1000);});}function zoom(f){const width=Math.max(35,Math.min(1000,box[2]*f)),height=width/2;box=[box[0]+(box[2]-width)/2,box[1]+(box[3]-height)/2,width,height];apply();}function fit(ps){if(!ps.length){box=[0,0,1000,500];apply();return;}const xs=ps.map(p=>(p.coordinates[0]+180)*1000/360),ys=ps.map(p=>(85-p.coordinates[1])*500/170);const xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys),width=Math.max(60,xmax-xmin+40,(ymax-ymin+30)*2);box=[(xmin+xmax-width)/2,(ymin+ymax-width/2)/2,Math.min(width,1000),Math.min(width,1000)/2];apply();}function filter(fitView=false){const r=$('#map-region').value,q=norm($('#map-search').value);const ps=plotted.filter(p=>(!r||p.region===r)&&(!q||norm(p.name_ru+' '+p.original_name+' '+p.city_ru+' '+p.country_ru).includes(q)));const ids=new Set(ps.map(p=>p.id));svg.querySelectorAll('[data-map-park]').forEach(a=>{a.style.display=ids.has(a.dataset.mapPark)?'':'none';});$('#map-match').textContent=`На карте по этому запросу: ${ps.length} из ${plotted.length}.`;if(fitView)fit(ps);}$('#map-plus').onclick=()=>zoom(.65);$('#map-minus').onclick=()=>zoom(1/.65);$('#map-reset').onclick=()=>{$('#map-region').value='';$('#map-search').value='';box=[0,0,1000,500];apply();filter();};$('#map-region').onchange=()=>filter(true);$('#map-search').oninput=()=>filter(true);svg.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,box:[...box]};moved=false;});svg.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)>6)moved=true;if(moved){svg.setPointerCapture(e.pointerId);const k=drag.box[2]/svg.getBoundingClientRect().width;box=[drag.box[0]-dx*k,drag.box[1]-dy*k,drag.box[2],drag.box[3]];apply();}});svg.addEventListener('pointerup',()=>{drag=null;});svg.addEventListener('pointercancel',()=>{drag=null;});svg.addEventListener('click',e=>{if(moved){e.preventDefault();e.stopPropagation();moved=false;}},true);filter();}
function typesPage(){main.innerHTML=`${header('Классификация','Один парк, несколько признаков','Тип объясняет, какое впечатление организует парк. Масштаб, аудитория, сезонность и размещение описывают другие стороны и могут пересекаться.')}<div class="type-list">${(DB.types||[]).map(t=>`<article><p class="eyebrow">${PARKS.filter(p=>p.types?.includes(t.id)).length} в каталоге</p><h2>${esc(t.title)}</h2><p>${esc(t.description)}</p><p><strong>На что смотреть:</strong> ${esc(t.watch)}</p><p class="small">${esc(t.limit)}</p><p class="small">${(t.examples||[]).filter(id=>byId[id]).map(id=>`<a href="#park/${id}">${esc(byId[id].name_ru)}</a>`).join(' · ')}</p><a class="small" href="#catalog?type=${t.id}">Парки этого типа →</a></article>`).join('')}</div><div class="chapter-body"><h2>Другие оси сравнения</h2>${(DB.axes||[]).map(a=>`<h3>${esc(a.axis)}</h3><p><strong>${esc(a.question)}</strong> ${esc(a.values)}</p>`).join('')}<p>Городской парк может быть одновременно историческим, семейным и тематизированным. Крытая среда не описывает содержание развлечений. Парк при курорте не равен всему курорту: гостиницы, соседний аквапарк и отдельный тематический парк учитываются раздельно, если это самостоятельные объекты.</p><p>Масштаб в атласе описывает роль места в поездке: городской, региональный или самостоятельная цель путешествия. Это редакционная классификация, а не официальный стандарт и не рейтинг качества.</p></div>`;}
function ideasPage(){const all=PARKS.flatMap(p=>(p.ideas||[]).map(i=>({p,i})));const topics={weather:'Погода и сезонность',compact:'Компактный участок',repeat:'Повторные визиты',ages:'Разные возраста вместе',access:'Доступность и отдых',queues:'Очереди и потоки',events:'Программа и события',evening:'Вечерний продукт',story:'Тема и недорогие детали',commerce:'Билеты, питание и продажи',city:'Связь с городом',operations:'Эксплуатация и обновление'};const params=new URLSearchParams(location.hash.split('?')[1]||'');main.innerHTML=`${header('Банк идей','Начать с решения','Смотрите, что именно сделано в парке, как это может работать и какие условия нужны для переноса. Это редакционные гипотезы для проверки в своем проекте.')}<div class="filters"><label>Задача или прием<input id="idea-search" type="search" value="${esc(params.get('q')||'')}" placeholder="Например, тень, зима, очередь, город"></label><label>Тема<select id="idea-topic"><option value="">Все задачи</option>${Object.entries(topics).map(([k,v])=>`<option value="${k}" ${params.get('topic')===k?'selected':''}>${v} (${all.filter(x=>x.i.topics?.includes(k)).length})</option>`).join('')}</select></label><label>Регион<select id="idea-region"><option value="">Весь мир</option>${Object.entries(REGIONS).map(([k,v])=>`<option value="${k}" ${params.get('region')===k?'selected':''}>${v}</option>`).join('')}</select></label></div><div id="idea-results"></div>`;const draw=()=>{const q=norm($('#idea-search').value),r=$('#idea-region').value,t=$('#idea-topic').value;const xs=all.filter(x=>(!r||x.p.region===r)&&(!t||x.i.topics?.includes(t))&&(!q||matches([x.i.title,x.i.observation,x.i.mechanism,x.i.conditions,x.i.limits,x.p.name_ru].join(' '),q)));const ps=new URLSearchParams();if(q)ps.set('q',$('#idea-search').value);if(r)ps.set('region',r);if(t)ps.set('topic',t);const hash='#ideas'+(ps.size?'?'+ps.toString():'');if(hash!==location.hash)history.replaceState(null,'',hash);$('#idea-results').innerHTML=`${xs.length ? `<p class="photo-count">${xs.length} ${plural(xs.length,'идея','идеи','идей')}</p>` : ''}<div class="reading">${xs.length?xs.map(x=>idea(x.p,x.i,true)).join(''):ideaRecovery(q,r,t,topics,all)}</div>`;};$('#idea-search').oninput=draw;$('#idea-region').onchange=draw;$('#idea-topic').onchange=draw;draw();}
function comparePage(params){const ps=comparisonParks(params);const example=params.get('parks')===economicsPair.join(',');main.innerHTML=`${header('Сопоставление','Увидеть различия','Сравнивайте решения в их контексте. Независимые признаки и исходные единицы полезнее единой оценки "лучше / хуже".')}<div class="actions">${example?'<a class="tag" href="#chapter/economics">Вернуться к главе об экономике</a>':'<a class="tag" href="#catalog">Добавить парки →</a>'}${ps.length?'<button data-export="compare-xlsx">Выгрузить сравнение XLSX</button>':''}</div>${ps.length?`<div class="compare-scroll"><table class="compare"><thead><tr><th>Параметр</th>${ps.map(p=>`<th>${p.photos?.[0]?`<img src="${p.photos[0].thumb||p.photos[0].file}" alt="${esc(p.name_ru)}">`:''}<a href="#park/${p.id}">${esc(p.name_ru)}</a>${example?'':`<p><button data-compare="${p.id}">Убрать</button></p>`}</th>`).join('')}</tr></thead><tbody>${[['Где',p=>esc([p.country_ru,p.city_ru].filter(Boolean).join(', '))],['Формат',p=>esc((p.types||[]).map(t=>TYPES[t]||t).join(', '))],['Масштаб',p=>esc(SCALES[p.scale]||p.scale)],['Среда',p=>esc(SETTINGS[p.setting]||p.setting)],['Аудитория',p=>esc((p.audience||[]).join('; ')||'Не выделена')],['Тематизация',p=>esc(p.theme_level||'Не выделена')],['Контекст',p=>esc(p.context||'Не установлен')],['Оплата',p=>esc(p.payment_model||'Уточняется')+(example?' <br>'+link(paymentSources[p.id],'Условия парка'):'')],['Оператор',p=>esc(p.operator||'Не установлен')],['Сезонность',p=>esc(p.seasonality||'Уточняется')],['Отличительные решения',p=>(p.highlights||[]).map(h=>`<p>${esc(h.text)} ${sources(p,h.source_ids)}</p>`).join('')],['Идеи переноса',p=>(p.ideas||[]).map(i=>`<p><strong>${esc(i.title)}</strong><br>${esc(i.conditions)}</p>`).join('')||'В базовой карточке не разбирались'],['Ограничения переноса',p=>(p.ideas||[]).map(i=>`<p>${esc(i.limits)}</p>`).join('')||'Требуется отдельное изучение'],['Числа и область учета',p=>(p.numbers||[]).map(n=>`<p>${esc(n.label)}: ${esc(numberText(n))} ${sources(p,n.source_ids)}</p>`).join('')||'Сопоставимые числа не установлены по изученным источникам'],['Статус',p=>esc([p.status?.label,p.status?.as_of].filter(Boolean).join(' · '))]].sort(([a],[b])=>example && params.get('row')==='payment'?Number(b==='Оплата')-Number(a==='Оплата'):0).map(([a,f])=>`<tr${example && a==='Оплата'?' class="payment-row"':''}><td>${a}</td>${ps.map(p=>`<td>${f(p)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:`<div class="empty"><h2>Выберите парки для сравнения</h2><p>Нажмите "Сравнить" в карточках каталога. Здесь можно сопоставить до шести парков.</p></div>`}`;}
function chaptersPage(id){if(id){const c=(DB.chapters||[]).find(x=>x.id===id);if(!c){main.innerHTML='<p>Глава не найдена.</p>';return;}main.innerHTML=`<a href="#chapters" class="backlink">← Все главы</a>${header('Как устроены парки',c.title,c.lead)}${id==='economics'?economicsExamples():''}<article class="chapter-body">${c.html||paras(c.text)}</article>${c.park_ids?.length?`<div class="section-head"><h2>Посмотреть на примерах</h2></div>${grid(c.park_ids.map(x=>byId[x]).filter(Boolean),id==='economics'?p=>p.payment_model:null)}`:''}${c.sources?.length?`<h2>Источники главы</h2>${sourceList(c.sources)}`:''}`;return;}main.innerHTML=`${header('Обзорные главы','Как устроены парки','История, экономика, планировка и гостевой опыт. Главы помогают читать отдельные примеры как части более широкой картины.')}<div class="chapter-list">${(DB.chapters||[]).map((c,i)=>`<a href="#chapter/${c.id}"><small>${String(i+1).padStart(2,'0')}</small><h2>${esc(c.title)}</h2><p>${esc(c.lead||'')}</p></a>`).join('')}</div>`;}
function methodPage(){main.innerHTML=`${header('Методика','Как читать этот атлас','Атлас предназначен для профессионального кругозора и поиска решений. Он помогает сформировать вопросы и подборку примеров для дальнейшего изучения.')}<article class="chapter-body">${DB.method_html||'<p>Каталог и подробные разборы используют открытые источники. Объем корпуса и заполненность проверяются при выпуске.</p>'}<h2>Практический маршрут</h2><ol><li>Откройте каталог и задайте регион, тип или интересующий прием.</li><li>Откройте подробную карточку. Сопоставьте описанное решение с фотографиями и источниками.</li><li>Добавьте несколько парков в сравнение. Проверьте условия и ограничения переноса.</li><li>Сохраните парки в подборку и выгрузите XLSX или CSV для обсуждения проекта.</li></ol><h2>Сохранение подборок и доступ к фотографиям</h2><p>Это публичная веб-версия атласа. Фотографии загружаются из Wikimedia Commons, Flickr и официальной галереи парка. Для них нужен интернет; доступность изображений зависит от внешних сервисов. Источники и условия использования указаны у каждого кадра. Полный локальный выпуск с фотографиями хранится у автора.</p><p>Подборки хранятся локально в этом браузере. При смене браузера или места хранения файла они могут быть недоступны. Для переноса используйте резервную копию JSON на странице "Моя подборка". Эта копия хранит выбранные парки, а не всю энциклопедию.</p><h2>Фотографии и планы</h2><p>У изображений указаны источник, автор и условия использования. Архивная фотография не подтверждает современное состояние. План может относиться к конкретному сезону. Редакционная схема, если она используется, подписана и не заменяет инженерный чертеж.</p><h2>Связь с энциклопедией аттракционов</h2><p>Атлас рассматривает парк целиком. Существующая энциклопедия помогает изучать отдельные типы, модели и производителей оборудования. ${link(DB.attractions_url||'https://konstantinpopov89.github.io/attractions-encyclopedia/','Открыть энциклопедию аттракционов')}</p></article>`;}
function allSourcesPage(){const map=new Map;for(const p of PARKS)for(const s of p.sources||[])if(!map.has(s.url))map.set(s.url,{...s,parks:[]});for(const p of PARKS)for(const s of p.sources||[])map.get(s.url)?.parks.push(p.id);const all=[...map.values()];main.innerHTML=`${header('Основания','Источники атласа',`${all.length} уникальных ссылок в карточках парков. У каждой карточки есть собственный список, связанный с ее фактами.`)}<div class="filters"><label>Найти источник<input id="source-search" type="search" placeholder="Парк, сайт, название материала"></label></div><div id="source-results"></div>`;function draw(){const q=norm($('#source-search').value);const ss=all.filter(s=>!q||norm(s.title+' '+s.url+' '+s.parks.map(id=>byId[id].name_ru).join(' ')).includes(q));$('#source-results').innerHTML=sourceList(ss);}$('#source-search').oninput=draw;draw();}
function exportRows(ps){const rows=[['Парк','Оригинальное название','Страна','Город','Долгота','Широта','Источник координат','Регион','Типы','Масштаб','Среда','Аудитория','Тематизация','Контекст','Модель оплаты','Оператор','Год открытия','Сезонность','Краткое описание','Особенности','Идеи','Наблюдения','Механизмы идей','Условия переноса','Ограничения','Числа с единицами и годом','Статус','Дата проверки статуса','Официальный сайт','Источники']];ps.forEach(p=>rows.push([p.name_ru,p.original_name,p.country_ru,p.city_ru,p.coordinates?.[0],p.coordinates?.[1],p.coordinates_source,REGIONS[p.region],(p.types||[]).map(t=>TYPES[t]||t).join('; '),SCALES[p.scale],SETTINGS[p.setting],(p.audience||[]).join('; '),p.theme_level,p.context,p.payment_model,p.operator,p.opened,p.seasonality,p.summary,(p.highlights||[]).map(h=>h.title+': '+h.text).join('\n'),(p.ideas||[]).map(i=>i.title).join('\n'),(p.ideas||[]).map(i=>i.title+': '+i.observation).join('\n'),(p.ideas||[]).map(i=>i.title+': '+i.mechanism).join('\n'),(p.ideas||[]).map(i=>i.title+': '+i.conditions).join('\n'),(p.ideas||[]).map(i=>i.title+': '+i.limits).join('\n'),(p.numbers||[]).map(n=>n.label+': '+numberText(n)).join('\n'),p.status?.label,p.status?.as_of,p.website,(p.sources||[]).map(s=>s.title+' | '+s.url+' | проверено '+s.checked_on).join('\n')].map(x=>x??'')));return rows;}
function download(name,bytes,type){const a=document.createElement('a');const u=URL.createObjectURL(new Blob([bytes],{type}));a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),10000);}
function csv(rows){return '\uFEFF'+rows.map(r=>r.map(c=>'"'+String(c??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(';')).join('\r\n');}
function exportSelection(kind){const ps=kind==='all-xlsx'?PARKS:kind.startsWith('compare-')?comparisonParks():saved.map(id=>byId[id]).filter(Boolean);if(!ps.length){toast('Сначала добавьте парки в подборку.');return;}if(kind==='json'){download('подборка-парков.json',JSON.stringify({format:'world-parks-selection',version:1,ids:ps.map(p=>p.id)},null,2),'application/json');return;}const rows=exportRows(ps);if(kind==='csv'){download('подборка-парков.csv',csv(rows),'text/csv;charset=utf-8');return;}const sourceRows=[['Парк','Источник','Ссылка','Тип','Дата материала','Дата проверки']];const ideaRows=[['Парк','Идея','Наблюдение','Механизм','Условия переноса','Ограничения','Источники']];for(const p of ps){for(const s of p.sources||[])sourceRows.push([p.name_ru,s.title,s.url,s.kind,s.published_on||'',s.checked_on||'']);for(const i of p.ideas||[])ideaRows.push([p.name_ru,i.title,i.observation,i.mechanism,i.conditions,i.limits,(i.source_ids||[]).map(id=>(p.sources||[]).find(s=>s.id===id)?.url||'').filter(Boolean).join('\n')]);}const sheets=[['Парки',rows],['Идеи',ideaRows],['Источники',sourceRows],['Как использовать',[['Принцип','Пояснение'],['Назначение','Подборка примеров для изучения и обсуждения, не инвестиционная рекомендация.'],['Сравнение','Сохраняйте год, валюту, единицы и область учета. Парк, курорт и оператор могут быть разными объектами.'],['Выводы','Факт, сообщение источника и редакционная интерпретация имеют разный доказательный статус.'],['Перенос','Проверьте условия применения идеи на своем участке и в своем режиме работы.']]]];download(kind==='all-xlsx'?'каталог-парков-мира.xlsx':'подборка-парков.xlsx',xlsx(sheets),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');}
async function importSelection(e){try{const f=e.target.files[0];if(!f)return;const d=JSON.parse(await f.text());if(d.format!=='world-parks-selection'||!Array.isArray(d.ids))throw Error('Неподходящий файл подборки');const ids=[...new Set(d.ids)].filter(id=>byId[id]);saved=[...new Set([...saved,...ids])];persist('saved',saved);badges();route(false);toast(`Восстановлено ${ids.length} парков. Прежняя подборка сохранена.`);}catch(e){toast(e.message||'Не удалось открыть подборку.');}}
function xlsx(sheets){const xml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));const col=n=>{let s='';for(n++;n;n=Math.floor((n-1)/26))s=String.fromCharCode(65+(n-1)%26)+s;return s;};const files={};files['[Content_Types].xml']=`<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>${sheets.map((_,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')}</Types>`;files['_rels/.rels']='<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>';files['xl/workbook.xml']=`<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>${sheets.map(([name],i)=>`<sheet name="${xml(name)}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')}</sheets></workbook>`;files['xl/_rels/workbook.xml.rels']=`<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${sheets.map((_,i)=>`<Relationship Id="rId${i+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join('')}<Relationship Id="rId${sheets.length+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>`;files['xl/styles.xml']='<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="2"><font><sz val="11"/><name val="Helvetica Neue"/></font><font><b/><sz val="11"/><name val="Helvetica Neue"/></font></fonts><fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf/></cellStyleXfs><cellXfs count="2"><xf fontId="0" fillId="0" borderId="0" xfId="0" applyAlignment="1"><alignment vertical="top" wrapText="1"/></xf><xf fontId="1" fillId="0" borderId="0" xfId="0" applyAlignment="1"><alignment vertical="top" wrapText="1"/></xf></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>';sheets.forEach(([name,rows],i)=>{const n=Math.max(...rows.map(r=>r.length));files[`xl/worksheets/sheet${i+1}.xml`]=`<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols>${Array.from({length:n},(_,j)=>`<col min="${j+1}" max="${j+1}" width="${j<4?24:48}" customWidth="1"/>`).join('')}</cols><sheetData>${rows.map((r,ri)=>`<row r="${ri+1}"${ri===0?' ht="28" customHeight="1"':''}>${r.map((v,ci)=>`<c r="${col(ci)}${ri+1}" s="${ri===0?1:0}" t="inlineStr"><is><t xml:space="preserve">${xml(String(v??'').replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g,''))}</t></is></c>`).join('')}</row>`).join('')}</sheetData><autoFilter ref="A1:${col(n-1)}${rows.length}"/></worksheet>`;});return zip(files);}
function zip(files){const te=new TextEncoder(),local=[],central=[];let offset=0;const crc=b=>{let c=0xffffffff;for(const x of b){c^=x;for(let i=0;i<8;i++)c=(c>>>1)^((c&1)?0xedb88320:0);}return(c^0xffffffff)>>>0;};const u16=(a,o,x)=>{a[o]=x&255;a[o+1]=(x>>>8)&255;};const u32=(a,o,x)=>{for(let i=0;i<4;i++)a[o+i]=(x>>>(8*i))&255;};for(const [name,text]of Object.entries(files)){const n=te.encode(name),b=te.encode(text),c=crc(b),l=new Uint8Array(30+n.length+b.length);u32(l,0,0x04034b50);u16(l,4,20);u16(l,6,0x0800);u32(l,14,c);u32(l,18,b.length);u32(l,22,b.length);u16(l,26,n.length);l.set(n,30);l.set(b,30+n.length);local.push(l);const h=new Uint8Array(46+n.length);u32(h,0,0x02014b50);u16(h,4,20);u16(h,6,20);u16(h,8,0x0800);u32(h,16,c);u32(h,20,b.length);u32(h,24,b.length);u16(h,28,n.length);u32(h,42,offset);h.set(n,46);central.push(h);offset+=l.length;}const cl=central.reduce((n,x)=>n+x.length,0),end=new Uint8Array(22);u32(end,0,0x06054b50);u16(end,8,local.length);u16(end,10,local.length);u32(end,12,cl);u32(end,16,offset);const result=new Uint8Array(offset+cl+22);let pos=0;for(const x of [...local,...central,end]){result.set(x,pos);pos+=x.length;}return result;}
function route(scroll=true){const place=history.state?.atlasPlace;if($('#lightbox').open)$('#lightbox').close();const [path,query='']=(location.hash.slice(1)||'home').split('?');const [page,id]=path.split('/');$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');$$('nav a').forEach(a=>a.classList.toggle('active',a.hash.slice(1)===(page==='park'?'catalog':page==='chapter'?'chapters':page)));document.title=(page==='park'&&byId[id]?byId[id].name_ru+' · ':'')+'Парки мира · Иллюстрированный атлас';if(page==='catalog')catalog(new URLSearchParams(query));else if(page==='saved')catalog(new URLSearchParams(query),saved.map(id=>byId[id]).filter(Boolean));else if(page==='park')parkPage(byId[id]);else if(page==='map')mapPage();else if(page==='types')typesPage();else if(page==='ideas')ideasPage();else if(page==='compare')comparePage(new URLSearchParams(query));else if(page==='chapters')chaptersPage();else if(page==='chapter')chaptersPage(id);else if(page==='market')marketPage();else if(page==='glossary')glossaryPage();else if(page==='method')methodPage();else if(page==='sources')allSourcesPage();else home();badges();syncButtons();initQueueCalculator();if(scroll)finishNavigation(page,id,new URLSearchParams(query),place);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-save],[data-compare],[data-photo],[data-export],[data-copy]');if(!b)return;if(b.dataset.save)toggleSaved(b.dataset.save);if(b.dataset.compare)toggleCompare(b.dataset.compare);if(b.dataset.photo)showLight(b.dataset.park,b.dataset.photo);if(b.dataset.export)exportSelection(b.dataset.export);if(b.dataset.copy)copyFinding(b.dataset.copy);});$('#menu-toggle').onclick=()=>{const open=$('#sidebar').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(open));};window.addEventListener('hashchange',()=>route());route();
window.__atlasQA={get parks(){return PARKS},exportRows,xlsx,photos:photoTotal};

function initQueueCalculator(){const fields=['q-seats','q-cycle','q-fill','q-availability'];if(!$('#q-seats'))return;const calculate=()=>{const [s,c,f,a]=fields.map(id=>Number($('#'+id).value));const valid=s>0&&s<=1000&&c>0&&c<=3600&&f>=0&&f<=100&&a>=0&&a<=100;$('#queue-result').textContent=valid?`Теоретически ${Math.round(s*3600/c).toLocaleString('ru-RU')} поездок пассажиров в час; с заданным заполнением и рабочим временем около ${Math.round(s*3600/c*f/100*a/100).toLocaleString('ru-RU')}.`:'Проверьте значения: места и цикл должны быть больше нуля, проценты от 0 до 100.';};for(const id of fields)$('#'+id).addEventListener('input',calculate);calculate();}
function glossaryPage(){main.innerHTML=`${header('Термины','Словарь RU / EN','Краткие рабочие определения для чтения карточек и источников. Значения конкретного договора, стандарта или методики могут отличаться.')}<div class="filters"><label>Русский или английский термин<input id="glossary-search" type="search" placeholder="Например, очередь, capacity, IP"></label></div><dl id="glossary-results" class="glossary"></dl>`;const draw=()=>{const q=norm($('#glossary-search').value);const ts=(DB.glossary||[]).filter(t=>!q||norm(t.ru+' '+t.en+' '+t.definition).includes(q));$('#glossary-results').innerHTML=ts.length?ts.map(t=>`<div><dt>${esc(t.ru)}<span>${esc(t.en)}</span></dt><dd>${esc(t.definition)}</dd></div>`).join(''):'<p>Термин не найден. Попробуйте другое написание.</p>';};$('#glossary-search').oninput=draw;draw();}
function marketPage(){const countryCounts=Object.entries(PARKS.reduce((acc,p)=>(acc[p.country_ru]=(acc[p.country_ru]||0)+1,acc),{})).sort((a,b)=>b[1]-a[1]);const known=PARKS.filter(p=>p.operator&&!/не установлен|не раскры|не определ|уточня/i.test(p.operator));main.innerHTML=`${header('Структура подборки','Операторы и охват','Числа ниже описывают состав этого атласа. Они не являются долями мирового рынка, рейтингом качества или полной переписью отрасли.')}<div class="stats"><div><strong>${PARKS.length}</strong><span>самостоятельных объектов</span></div><div><strong>${countryCounts.length}</strong><span>стран и территорий</span></div><div><strong>${PARKS.filter(p=>p.deep).length}</strong><span>подробных разборов</span></div></div><p><button data-export="all-xlsx">Скачать весь каталог XLSX</button></p><h2>География каталога</h2><div class="coverage-table"><table><thead><tr><th>Макрорегион</th><th>Каталог</th><th>Подробные</th><th>С фотографиями</th></tr></thead><tbody>${Object.entries(REGIONS).map(([id,n])=>{const ps=PARKS.filter(p=>p.region===id);return `<tr><td><a href="#catalog?region=${id}">${n}</a></td><td>${ps.length}</td><td>${ps.filter(p=>p.deep).length}</td><td>${ps.filter(p=>p.photos?.length).length}</td></tr>`}).join('')}</tbody></table></div><div class="country-bars">${countryCounts.map(([c,n])=>`<a href="#catalog?country=${encodeURIComponent(c)}"><span>${esc(c)}</span><i style="width:${Math.max(2,n/countryCounts[0][1]*100)}%"></i><strong>${n}</strong></a>`).join('')}</div><h2>Россия и СНГ внутри мирового каталога</h2><p>${PARKS.filter(p=>RUCIS_CODES.includes(p.country_code)).length} парков, из них ${PARKS.filter(p=>RUCIS_CODES.includes(p.country_code)&&p.deep).length} подробных. Они уже входят в макрорегиональные итоги и повторно не прибавляются. В текущем отборе: ${[...new Set(PARKS.filter(p=>RUCIS_CODES.includes(p.country_code)).map(p=>p.country_ru))].sort((a,b)=>a.localeCompare(b,'ru')).map(esc).join(', ')}.</p><p><a href="#catalog?group=ru-cis">Открыть эту подборку →</a></p><h2>Кто управляет парками</h2><p class="lead">Оператор, собственник, правообладатель темы и изготовитель оборудования могут быть разными организациями.</p><p>В списке сохранены формулировки карточек и их источники. Бренд сети не считается автоматически юридическим владельцем. Показатели группы не переносятся на отдельный парк.</p><div class="filters"><label>Оператор или парк<input id="operator-search" type="search" placeholder="Например, Miral, фонд, муниципальный"></label></div><div id="operators"></div><p class="note">Обзор отраслевых отчетов и правил сравнения: <a href="#chapter/economics">Экономика</a> · <a href="#chapter/sources-guide">Тренды и источники</a>.</p>`;const draw=()=>{const q=norm($('#operator-search').value);const ps=known.filter(p=>!q||norm(p.operator+' '+p.name_ru+' '+p.country_ru).includes(q));$('#operators').innerHTML=`<p class="small muted">${ps.length} карточек с установленным по изученным источникам оператором.</p><div class="operator-list">${ps.map(p=>`<article><h3>${esc(p.operator)}</h3><p><a href="#park/${p.id}">${esc(p.name_ru)}</a> · ${esc(p.country_ru)}</p></article>`).join('')}</div>`;};$('#operator-search').oninput=draw;draw();}

function attractionLinks(p){if(!p.attraction_links?.length)return '';return `<section id="attraction-links"><h2>От парка к оборудованию</h2><p class="small muted">Указаны только найденные соответствия. Название поездки, тип и заводская модель могут различаться.</p>${p.attraction_links.map(a=>`<article class="idea"><h3>${esc(a.ride||a.name||'Аттракцион')}</h3><p>${a.zone?`Зона: ${esc(a.zone)}. `:''}${a.manufacturer?`Изготовитель: ${esc(a.manufacturer)}. `:''}${a.model?`Модель / семейство: ${esc(a.model)}. `:''}${a.catalog_model?`В энциклопедии ищите: ${esc(a.catalog_model)}. `:''}${sources(p,a.source_ids)}</p>${a.encyclopedia_url?`<p>${link(a.encyclopedia_url,'Точное соответствие в энциклопедии аттракционов')}</p>`:a.manufacturer_url?`<p>${link(a.manufacturer_url,'Профиль изготовителя в энциклопедии')}</p>`:'<p class="small muted">Точная карточка модели в связанном каталоге не установлена; общую категорию не выдаем за модель.</p>'}</article>`).join('')}</section>`;}
